package main

import \(
	"fmt"
	"golang.org/x/crypto/bcrypt"
	"gorm.io/driver/mysql"
	"gorm.io/gorm"
\)

func main\(\) {
	dsn := "email:tgiyGk32@tcp\(110.42.111.49:1244\)/email?charset=utf8mb4&parseTime=True&loc=Asia%2FShanghai"
	db, err := gorm.Open\(mysql.Open\(dsn\), &gorm.Config{}\)
	if err != nil {
		fmt.Println\("连接失败:", err\)
		return
	}

	// 查看 root 用户
	var results []map[string]interface{}
	db.Raw\("SELECT id, username, password, status, token_version FROM user WHERE username = 'root'"\).Scan\(&results\)
	fmt.Println\("当前 root 用户:", len\(results\), "条"\)
	for _, r := range results {
		fmt.Printf\("  id=%v status=%v token_version=%v password_len=%d\\n", r["id"], r["status"], r["token_version"], len\(fmt.Sprintf\("%v", r["password"]\)\)\)
	}

	// 生成新密码 hash
	hash, err := bcrypt.GenerateFromPassword\([]byte\("sunny521"\), bcrypt.DefaultCost\)
	if err != nil {
		fmt.Println\("hash失败:", err\)
		return
	}

	// 更新密码
	result := db.Exec\("UPDATE user SET password = ?, status = 1, token_version = 1 WHERE username = 'root'", string\(hash\)\)
	fmt.Printf\("更新 %d 行, err=%v\\n", result.RowsAffected, result.Error\)

	if result.RowsAffected == 0 {
		// root 不存在，创建
		result = db.Exec\("INSERT INTO user \(id, username, password, role, status, token_version, created_at, updated_at\) VALUES \(UUID\(\), 'root', ?, 2, 1, 1, NOW\(\), NOW\(\)\)", string\(hash\)\)
		fmt.Printf\("创建 root 用户: %d 行, err=%v\\n", result.RowsAffected, result.Error\)
	}

	fmt.Println\("完成! root 密码已重置为 sunny521"\)
}
GOEOF)
